//! Empty Esri mobile geodatabases (`.geodatabase`): SQLite files with the geodatabase system
//! tables. The schema and system rows are those of a geodatabase ArcGIS Pro 3.7's Create Mobile
//! Geodatabase writes (`mobile_seed.rs`, generated by `scripts/research/mobile_gdb_seed.py`); the
//! creation times and item UUIDs are this file's own.

use std::hash::{BuildHasher, Hasher};
use std::path::Path;

use chrono::{Local, Utc};
use unigis_core::{Error, Result};

use crate::sqlite::SqlValue;
use crate::sqlite_writer::{Options, ValueRef, Writer};

/// A seed value; the placeholders are filled in per file.
#[derive(Debug, Clone, Copy)]
pub(crate) enum V {
    N,
    I(i64),
    R(f64),
    T(&'static str),
    #[allow(dead_code)]
    B(&'static [u8]),
    /// Creation time, UTC seconds.
    Now,
    /// Creation time, UTC seconds as a real.
    NowReal,
    /// Creation time, local seconds.
    NowLocal,
    /// The n-th item UUID.
    Uuid(usize),
    /// Text with the local creation time (`2026-10-30T13:37:28`) in place of `{T}`.
    LocalTime(&'static str),
}

/// A `sqlite_master` entry, in ArcGIS's order.
pub(crate) enum Entry {
    Table {
        name: &'static str,
        sql: &'static str,
        rows: &'static [(i64, &'static [V])],
    },
    /// An index; `columns` are the key columns' positions in the table (-1: the rowid).
    Index {
        name: &'static str,
        table: &'static str,
        sql: Option<&'static str>,
        columns: &'static [i64],
    },
    /// A virtual table or trigger: a schema row without data.
    Raw {
        kind: &'static str,
        name: &'static str,
        table: &'static str,
        sql: &'static str,
    },
}

/// The `application_id` of mobile geodatabases: "Esri".
const ESRI: u32 = 0x4573_7269;

/// Writes an empty mobile geodatabase at `path` (which must not exist).
pub fn create(path: &Path) -> Result<()> {
    if path.exists() {
        return Err(Error::Unsupported(format!(
            "ERROR 000258: Output {} already exists",
            path.display()
        )));
    }
    let utc = Utc::now();
    let now = utc.timestamp();
    let local = utc.with_timezone(&Local);
    let now_local = now + i64::from(local.offset().local_minus_utc());
    let iso = local.format("%Y-%m-%dT%H:%M:%S").to_string();
    let uuids: Vec<String> = (0..8).map(|_| uuid()).collect();
    let value = |v: &V| -> SqlValue {
        match *v {
            V::N => SqlValue::Null,
            V::I(i) => SqlValue::Integer(i),
            V::R(r) => SqlValue::Real(r),
            V::T(t) => SqlValue::Text(t.to_string()),
            V::B(b) => SqlValue::Blob(b.to_vec()),
            V::Now => SqlValue::Integer(now),
            V::NowReal => SqlValue::Real(now as f64),
            V::NowLocal => SqlValue::Integer(now_local),
            V::Uuid(k) => SqlValue::Text(uuids.get(k).cloned().unwrap_or_default()),
            V::LocalTime(t) => SqlValue::Text(t.replace("{T}", &iso)),
        }
    };
    let mut w = Writer::create(
        path,
        Options {
            page_size: 4096,
            application_id: ESRI,
            user_version: 0,
        },
    )?;
    let mut tables: Vec<(&str, Vec<crate::sqlite::Row>)> = Vec::new();
    for entry in crate::mobile_seed::SCHEMA {
        match entry {
            Entry::Table { name, sql, rows } => {
                let rows: Vec<crate::sqlite::Row> = rows
                    .iter()
                    .map(|(id, cells)| (*id, cells.iter().map(value).collect()))
                    .collect();
                let mut t = w.table(name, sql);
                for (id, cells) in &rows {
                    let refs: Vec<ValueRef> = cells.iter().map(SqlValue::as_value_ref).collect();
                    t.push(*id, &refs)?;
                }
                t.finish()?;
                tables.push((name, rows));
            }
            Entry::Index {
                name,
                table,
                sql,
                columns,
            } => {
                let rows = tables
                    .iter()
                    .find(|(n, _)| n == table)
                    .map(|(_, r)| r.as_slice())
                    .unwrap_or_default();
                let entries = rows
                    .iter()
                    .map(|(id, cells)| {
                        let key = columns
                            .iter()
                            .map(|&c| match usize::try_from(c) {
                                Ok(c) => cells.get(c).cloned().unwrap_or(SqlValue::Null),
                                Err(_) => SqlValue::Integer(*id),
                            })
                            .collect();
                        (key, *id)
                    })
                    .collect();
                w.index(name, table, *sql, entries)?;
            }
            Entry::Raw {
                kind,
                name,
                table,
                sql,
            } => w.schema_entry(kind, name, table, sql),
        }
    }
    w.finish()
}

/// A random (version 4) UUID in ArcGIS's `{...}` upper-case form.
fn uuid() -> String {
    let mut bytes = [0u8; 16];
    for half in bytes.chunks_mut(8) {
        let mut h = std::collections::hash_map::RandomState::new().build_hasher();
        h.write_u128(Utc::now().timestamp_nanos_opt().unwrap_or_default() as u128);
        half.copy_from_slice(&h.finish().to_le_bytes());
    }
    bytes[6] = (bytes[6] & 0x0F) | 0x40;
    bytes[8] = (bytes[8] & 0x3F) | 0x80;
    let h: Vec<String> = bytes.iter().map(|b| format!("{b:02X}")).collect();
    format!(
        "{{{}-{}-{}-{}-{}}}",
        h[..4].concat(),
        h[4..6].concat(),
        h[6..8].concat(),
        h[8..10].concat(),
        h[10..].concat()
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_arcgis_system_tables() {
        let dir = std::env::temp_dir().join(format!("unigis-mobile-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("new.geodatabase");
        let _ = std::fs::remove_file(&path);
        create(&path).unwrap();
        let db = crate::sqlite::Database::open(&path).unwrap();
        let count = |t: &str| db.select(db.table(t).unwrap()).unwrap().len();
        assert_eq!(count("GDB_Items"), 3);
        assert_eq!(count("GDB_ItemTypes"), 38);
        let err = create(&path).unwrap_err().to_string();
        assert!(err.contains("000258"), "{err}");
        std::fs::remove_dir_all(dir).unwrap();
    }
}
